#define debugArr(...) std::cerr << __LINE__ << ": [", __DEBUG_UTIL__::printerArr(#__VA_ARGS__, __VA_ARGS__)
#else
#define debug(...)
#define debugArr(...)
#endif
const int maxn = 1e5 + 5;
pair<int, int> a[maxn];
pair<int, int> queries[maxn];
int ans_[maxn];
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    freopen("islands.INP", "r", stdin);
    freopen("islands.OUT", "w", stdout);

    int n, q;
    cin >> n >> q;
    int tmp = 1;
    for (int i = 1; i <= n; i++) {
        int c; cin >> c;
        for (int j = 0; j < c; j++) {
            int s; cin >> s;
            a[tmp++] = {s, i};
        }
    }
    for (int i = 1; i <= q; i++) {
        cin >> queries[i].first;
        queries[i].second = i;
    }

    sort(a + 1, a + 1 + tmp);
    sort(queries + 1, queries + 1 + q);
    reverse(a + 1, a + 1 + tmp);
    reverse(queries + 1, queries + 1 + q);
    vector<int> cnt(n + 1, 0);

    int tmp_ = 0;
    int ans = n + 1;
    int cur = 1;
    for(int i = 1; i <= q; i++) {
        while (cur <= tmp && a[cur].first >= queries[i].first) {
            int r = a[cur].second;
            cnt[r]++;
            if (cnt[r] > tmp_ || (cnt[r] == tmp_ && r > ans)) {
                tmp_ = cnt[r];
                ans = r;
            }
            cur++;
        }
        ans_[queries[i].second] = ans;
    }

    for (int i = 1; i <= q; i++) {
        cout << ans_[i] << "\n";
    }
}